def wrap(a):
    while a > 180:
        a -= 360
    while a <= -180:
        a += 360
    return a

def drive(me, enemy, arena):
    b = bearing_to(enemy.x, enemy.y)
    if abs(b) <= 90:
        v = 1.0
        e = b
    else:
        v = -1.0
        e = wrap(b - 180)
    w = 0.02 * e
    left = v - w
    right = v + w
    left = max(-1.0, min(1.0, left))
    right = max(-1.0, min(1.0, right))
    return (left, right)

